cases.setup_script:
export PYTHONDONTWRITEBYTECODE=1 H=/opt/bashos-parity/harness/helpers/system-seccomp.py
out=$(/usr/bin/python3 "$H" --errno uname:EFAULT -- /usr/bin/uname -s 2>&1) && { echo "CONTROL-FAILED uname rule not applied"; exit 98; }
[[ $out == *"Bad address"* ]] || { echo "CONTROL-FAILED unexpected control diagnostic"; exit 98; }

files.hostid.sh:
mark() { printf '[%s]\n' "$1"; printf '[%s]\n' "$1" >&2; }
/usr/bin/ln -s /tmp/parity-case/hostid.cur /etc/hostid || exit 96
put() { /usr/bin/python3 -c 'import sys; open("/tmp/parity-case/hostid.cur", "wb").write(bytes.fromhex(sys.argv[1]))' "$1"; }
show() { /usr/bin/python3 -c 'print("etc-hostid=" + open("/etc/hostid", "rb").read().hex())'; }
run() { mark "$1"; hostid; printf '[%s] status=%d\n' "$1" "$?"; }
put 01020304; show
export BASHHOSTID_MACHINE_ID_PATH=$PWD/good.txt; run override-valid
export BASHHOSTID_MACHINE_ID_PATH=$PWD/upper.txt; run override-uppercase
export BASHHOSTID_MACHINE_ID_PATH=$PWD/bad.txt; run override-invalid
unset BASHHOSTID_MACHINE_ID_PATH; run no-override
